'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let state=null, filter='all', query='', poll=null, toastTimer;
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const glyph={agent:['bot','berry'],portainer:['layers','blue'],postgres:['hard','purple'],ollama:['spark','gold'],nextcloud:['cloud','blue'],office:['layers','berry'],n8n:['activity','purple'],zap:['shield','green'],'zap-api':['terminal','green'],vpn:['lock','gold']};
const labels={terminal:'ТЕРМИНАЛ',overview:'ОБЗОР',services:'СЕРВИСЫ',system:'СИСТЕМА',alerts:'УВЕДОМЛЕНИЯ',settings:'НАСТРОЙКИ',files:'ФАЙЛЫ',cluster:'УЗЛЫ PI',vault:'ПАРОЛИ И СЕКРЕТЫ',network:'СЕТЬ',chat:'ИИ ЧАТ',knowledge:'БАЗА ЗНАНИЙ',tunnels:'ТУННЕЛИ'};
const names={agent:'Agent Zero',portainer:'Portainer',postgres:'PostgreSQL',ollama:'Ollama',nextcloud:'Nextcloud',office:'ONLYOFFICE',n8n:'n8n',zap:'OWASP ZAP','zap-api':'ZAP API',vpn:'Gluetun',vnc:'VNC',desktop:'HDMI','mode-docs':'Документы','office-lan':'ONLYOFFICE','office-tail':'ONLYOFFICE'};
function toast(msg){const x=$('#toast');x.textContent=msg;x.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>x.classList.remove('visible'),4200)}
async function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...opt,headers:{...(opt.body?{'Content-Type':'application/json'}:{}),...(opt.headers||{})}});let d={};try{d=await r.json()}catch(e){} if(r.status===401&&path!='/api/login'){showLogin();throw Error('Сессия завершена')}if(!r.ok)throw Error(d.error||d.message||'Ошибка соединения');return d}
function showLogin(){lockVault();$('#app').classList.add('hidden');$('#login').classList.remove('hidden');if(poll)clearInterval(poll);poll=null}
function showApp(){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');load();loadTelegram();if(!poll)poll=setInterval(load,Number(localStorage.getItem('pi-refresh-rate'))||10000)}
function go(page){if(!labels[page])return;$$('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));$$('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#crumb').textContent=labels[page];window.scrollTo({top:0,behavior:'smooth'});if(page==='system')diskPoll();if(page==='terminal')termTargets();if(page==='alerts')loadTelegram();if(page==='knowledge'){loadKnowledge();kbLoad()};if(page==='tunnels')loadExtras();if(page==='settings'){loadWifi();loadModels();loadBackup();loadInterfaces()}if(page==='chat'){loadChats();loadModels()}if(page==='network'){loadNetwork();loadHistory()}if(page==='vault')loadVaultInfo();if(page==='files'&&typeof fmActivate==='function')fmActivate();if(page==='cluster'){loadCluster();nodeopsTargets()}}
function prettyBytes(n){if(!Number.isFinite(n))return '—';return (n/1073741824).toFixed(1)+' ГБ'}
function pct(n,d){return d?Math.max(0,Math.min(100,Math.round(n/d*100))):0}
function metric(container,label,value,unit,foot,percent,ico){const card=document.createElement('div');card.className='metric';const head=document.createElement('div');head.className='metric-head';const text=document.createElement('span');text.textContent=label;head.append(text);const pic=document.createElement('span');pic.innerHTML=icon(ico);head.append(pic);const v=document.createElement('div');v.className='metric-value';v.append(document.createTextNode(value+' '));const small=document.createElement('small');small.textContent=unit;v.append(small);const f=document.createElement('div');f.className='metric-foot';const ft=document.createElement('span');ft.textContent=foot;f.append(ft);const progress=document.createElement('progress');progress.className='progress';progress.max=100;progress.value=percent;progress.setAttribute('aria-label',label);card.append(head,v,f,progress);container.append(card)}
function renderMetrics(target,s){target.replaceChildren();const cp=s.cpu==null?'—':String(s.cpu);metric(target,'Процессор',cp,'%','Загрузка CPU',s.cpu||0,'chip');metric(target,'Оперативная память',prettyBytes(s.memory_used).replace(' ГБ',''),'ГБ','из '+prettyBytes(s.memory_total),pct(s.memory_used,s.memory_total),'activity');metric(target,'Температура',s.temperature==null?'—':String(s.temperature),'°C','Температура CPU',Math.min(100,(s.temperature||0)),'temp');metric(target,'Хранилище',prettyBytes(s.disk_used).replace(' ГБ',''),'ГБ','из '+prettyBytes(s.disk_total),pct(s.disk_used,s.disk_total),'hard')}
function makeService(x){const card=document.createElement('article');card.className='service-card';const [ic,col]=glyph[x.id]||['layers','green'];const top=document.createElement('div');top.className='service-top';const badge=document.createElement('span');const running=x.state==='running';badge.className='badge '+(running?'success':'neutral');badge.textContent=running?'●  РАБОТАЕТ':x.state==='restarting'?'ПЕРЕЗАПУСК':'ВЫКЛЮЧЕН';const mark=document.createElement('div');mark.className='service-icon '+col;mark.innerHTML=icon(ic);top.append(mark,badge);const title=document.createElement('h3');title.textContent=x.name;const desc=document.createElement('p');desc.textContent=x.id==='vpn'&&!state.vpn_configured?'Нужна конфигурация WireGuard':x.desc;const actions=document.createElement('div');actions.className='service-actions';if(x.port){let open=document.createElement('a');open.className='card-open'+(running?'':' disabled');open.textContent='Открыть ';if(running){open.href=x.scheme+'://'+location.hostname+':'+x.port+(x.path||'/');open.target='_blank';open.rel='noopener noreferrer'}else{open.href='#';open.addEventListener('click',e=>e.preventDefault())}const symbol=document.createElement('span');symbol.innerHTML=icon('external');open.append(symbol);actions.append(open)}else{const label=document.createElement('span');label.className='card-open disabled';label.textContent=x.id==='postgres'?'Доступна внутри Docker':x.id==='zap-api'?'Доступна внутри Docker':running?'Сервис активен':'По требованию';actions.append(label)}if(true){const b=document.createElement('button');b.className='toggle'+(running?' stop':'');b.textContent=running?'Остановить':'Запустить';b.dataset.action=x.id+':'+(running?'stop':'start');b.disabled=Boolean(state.task.running)||(x.id==='vpn'&&!state.vpn_configured);actions.append(b)}const meta=document.createElement('div');meta.className='service-meta';meta.textContent=running ? `${x.status} · CPU ${x.cpu_usage||'—'} · RAM ${x.memory_usage||'—'}` : x.status;card.append(top,title,desc,meta,actions);if(x.limits){let limit=document.createElement('button');limit.className='resource-button';limit.textContent='Ресурсы · '+(x.limits.memory?(x.limits.memory/1048576).toFixed(0)+' МиБ':'RAM без лимита')+' · '+(x.limits.cpus||'∞')+' CPU';limit.onclick=()=>openLimits(x);card.append(limit)}return card}
function renderServices(){if(!state)return;const all=state.services;let selected=all.filter(x=>(filter==='all'||(filter==='running'?x.state==='running':x.state!=='running'))&&((x.name+' '+x.desc).toLowerCase().includes(query)));const target=$('#all-services');target.replaceChildren();if(!selected.length){const e=document.createElement('div');e.className='empty';e.textContent='Сервисы не найдены';target.append(e)}else selected.forEach(x=>target.append(makeService(x)));const overview=$('#overview-services');overview.replaceChildren();['agent','nextcloud','ollama','n8n'].map(id=>all.find(x=>x.id===id)).filter(Boolean).forEach(x=>overview.append(makeService(x)));$('#nav-running').textContent=all.filter(x=>x.state==='running').length}
function details(target,rows){target.replaceChildren();for(const [name,value] of rows){const r=document.createElement('div');r.className='detail-row';const a=document.createElement('span');a.textContent=name;const b=document.createElement('strong');b.textContent=value||'—';r.append(a,b);target.append(r)}}
const cpuHistory=[];function display(d){state=d;const s=d.system;if(s.cpu!=null){cpuHistory.push(s.cpu);if(cpuHistory.length>45)cpuHistory.shift()}$('#cpu-line').setAttribute('points',cpuHistory.map((v,i)=>`${i*500/44},${78-Math.min(100,Math.max(0,v))*.76}`).join(' '));$('#chart-cpu').textContent=(s.cpu??'—')+' %';$('#chart-memory').textContent=prettyBytes(s.memory_used)+' / '+prettyBytes(s.memory_total);$('#chart-temp').textContent=(s.temperature??'—')+' °C';$('#chart-wifi').textContent=s.wifi||'—';renderMetrics($('#metrics'),s);renderMetrics($('#system-metrics'),s);renderServices();$('#overview-wifi').textContent=s.wifi||'—';$('#overview-tail').textContent=s.tailscale_ip||'—';const t=Math.floor(s.uptime/3600),up=Math.floor(t/24)+' д '+(t%24)+' ч';const rows=[['Сеть Wi-Fi',s.wifi],['Локальный IPv4',s.lan_ip],['Tailscale IPv4',s.tailscale_ip],['Время работы',up]];details($('#network-details'),rows);details($('#settings-network'),rows.slice(0,3));$('#vnc-status').textContent=d.vnc?'Запущен · порт 5901':'Выключен';$('#desktop-status').textContent=d.desktop?'Запущен':'Выключен';const health=$('#power-detail');health.classList.toggle('warning',s.undervoltage_now||s.undervoltage_previous||s.throttled_now);health.textContent=s.undervoltage_now?'Сейчас обнаружено пониженное напряжение.':s.undervoltage_previous?'С момента запуска было зафиксировано пониженное напряжение.':'Признаков проблем с питанием не обнаружено.';$('#updated-time').textContent=new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit'});$('#connection-label').textContent='Подключено';$('.live-pill').classList.remove('offline');$$('[data-action]').forEach(b=>{if(b.closest('.service-card'))return;b.disabled=!!d.task.running});if(d.task&&!d.task.running&&d.task.result&&d.task.time&&d.task.time!==display.last){display.last=d.task.time;toast(d.task.result)}}
async function load(){try{display(await api('/api/status'))}catch(e){if($('#login').classList.contains('hidden')){$('#connection-label').textContent='Нет связи';$('.live-pill').classList.add('offline')}}}
async function loadTelegram(){try{let d=await api('/api/telegram');$('#telegram-badge').textContent=d.configured?(d.enabled?'ПОДКЛЮЧЕНО':'ОТКЛЮЧЕНО'):'НЕ НАСТРОЕНО';$('#telegram-badge').className='badge '+(d.configured&&d.enabled?'success':'neutral');$('#chat-id').value=d.chat_id||'';$('#telegram-enabled').checked=d.configured?d.enabled:true;$('#bot-token').placeholder=d.configured?'Токен сохранён · введите новый для замены':'Вставьте токен от BotFather'}catch(e){}}
async function action(value){const [service,action]=value.split(':');if(!service||!action)return;if(service==='pihole'&&action==='start'&&!confirm('Pi-hole откроет DNS-порт 53 на сетевых интерфейсах Raspberry Pi. Запустить?'))return;if(action==='stop'&&!confirm('Остановить '+(names[service]||'сервис')+'?'))return;try{const r=await api('/api/action',{method:'POST',body:JSON.stringify({service,action})});toast(r.message);await load()}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){go(page.dataset.page);return}const nav=e.target.closest('[data-go]');if(nav){go(nav.dataset.go);return}const act=e.target.closest('[data-action]');if(act&&!act.disabled){action(act.dataset.action);return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===f));renderServices()}});
