async function logout(){lockVault();try{await api('/api/logout',{method:'POST',body:'{}'})}catch(e){}showLogin()}$('#logout').addEventListener('click',logout);$('#logout-settings').addEventListener('click',logout);
$('#telegram-form').addEventListener('submit',async e=>{e.preventDefault();const msg=$('#telegram-message');msg.textContent='Сохраняем…';try{let d=await api('/api/telegram',{method:'POST',body:JSON.stringify({bot_token:$('#bot-token').value,chat_id:$('#chat-id').value,enabled:$('#telegram-enabled').checked})});$('#bot-token').value='';msg.textContent=d.message;await loadTelegram();toast(d.message)}catch(err){msg.textContent=err.message}});
$('#telegram-test').addEventListener('click',async()=>{let m=$('#telegram-message');m.textContent='Отправляем…';try{let d=await api('/api/telegram/test',{method:'POST',body:'{}'});m.textContent=d.message;toast(d.message)}catch(e){m.textContent=e.message}});
