async function loadExtras(){try{let d=await api('/api/extras');$('#tunnel-status').textContent=d.tunnel.status;$('#tunnel-url').textContent=d.tunnel.url||'—';$('#cloudflared-status').textContent=d.installed?'Установлен':'Не установлен';$('#models').textContent=d.models.join(', ')||'Нет запущенных моделей или Ollama выключена';fillModelLists(d.models);}catch(e){toast(e.message)}}
async function loadKnowledge(){try{let d=await api('/api/knowledge');let root=$('#notes-list');root.replaceChildren();d.notes.forEach(n=>{let b=document.createElement('button');b.className='note-item';b.textContent=n.title;b.dataset.search=(n.title+' '+n.text).toLowerCase();b.addEventListener('click',()=>{if(n.source==='workspace'){toast('Откройте Markdown в файловом разделе базы знаний.');return}$('#note-title').value=n.title;$('#note-body').value=n.text});root.append(b)});if(!d.notes.length)root.textContent='Пока нет заметок';loadExtras()}catch(e){toast(e.message)}}
