$('#refresh-rate').value=localStorage.getItem('pi-refresh-rate')||'10000';$('#refresh-rate').addEventListener('change',e=>{localStorage.setItem('pi-refresh-rate',e.target.value);if(poll)clearInterval(poll);poll=setInterval(load,Number(e.target.value));toast('Интервал обновления сохранён')});

$('#note-import').addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;if(f.size>18000){toast('Файл слишком большой: максимум 18 КБ');return}let t=await f.text();if(t.length>6000){toast('Текст слишком длинный: максимум 6000 символов');return}$('#note-title').value=f.name.replace(/\.(txt|md)$/i,'');$('#note-body').value=t;toast('Файл загружен в редактор. Нажмите «Сохранить заметку».')});

function fillModelLists(models){for(const sel of [$('#ai-model'),$('#manage-model')]){let prev=sel.value;sel.replaceChildren();if(!models.length){let o=document.createElement('option');o.value='';o.textContent='Запустите Ollama и обновите список';sel.append(o)}for(const name of models){let o=document.createElement('option');o.value=name;o.textContent=name;sel.append(o)}if(models.includes(prev))sel.value=prev}}
async function loadModels(){try{let d=await api('/api/extras');fillModelLists(d.models);$('#models').textContent=d.models.join(', ')||'Ollama выключена или моделей нет'}catch(e){toast(e.message)}}
$('#model-refresh').onclick=loadModels;$('#models-refresh').onclick=loadModels;for(const op of ['pull','load','unload','delete'])$('#model-'+op).onclick=async()=>{let name=op==='pull'?$('#pull-model').value.trim():$('#manage-model').value;if(!name)return toast('Укажите модель');if(op==='delete'&&!confirm('Удалить модель '+name+' с диска? Для повторного использования её потребуется скачать заново.'))return;try{toast(op==='load'?'Загружаем модель в память…':'Выполняем…');let d=await api('/api/feature/model',{method:'POST',body:JSON.stringify({op,name})});toast(d.message||'Готово');loadModels()}catch(e){toast(e.message)}};
