let wifiObservation={};let wifiProfiles=[];async function loadWifi(){try{wifiObservation=await api('/api/wifi-observations');let d=await api('/api/wifi');wifiProfiles=d.profiles;let root=$('#wifi-list');root.replaceChildren();for(const w of wifiProfiles){let row=document.createElement('div');row.className='wifi-row';let info=document.createElement('div');let strong=document.createElement('strong');strong.textContent=w.ssid||w.name;let small=document.createElement('small');small.textContent=' · '+w.name+(w.active?' · подключено':'')+(w.hidden?' · скрытая':'');info.append(strong,small);let ob=(wifiObservation.observations||{})[w.uuid]||{};let extra=document.createElement('small');extra.textContent=' · локальный IP: '+(ob.internal_ip||'—')+' · внешний IP Wi-Fi: '+(ob.external_ip||'—')+(w.active&&ob.signal?' · сигнал '+ob.signal+'%':'');info.append(extra);let controls=document.createElement('div');for(const [op,label] of [['connect','Подключить'],['edit','Изменить'],['delete','Удалить']]){let b=document.createElement('button');b.className='button small-btn secondary';b.textContent=label;b.disabled=w.active&&(op==='delete'||op==='connect');b.onclick=()=>wifiAction(op,w);controls.append(b)}row.append(info,controls);root.append(row)}}catch(e){toast(e.message)}}
function clearWifi(){$('#wifi-uuid').value='';$('#wifi-name').value='';$('#wifi-ssid').value='';$('#wifi-password').value='';$('#wifi-hidden').checked=false;$('#wifi-auto').checked=true}$('#wifi-cancel').onclick=clearWifi;$('#wifi-refresh').onclick=loadWifi;
async function wifiAction(op,w){if(op==='edit'){$('#wifi-uuid').value=w.uuid;$('#wifi-name').value=w.name;$('#wifi-ssid').value=w.ssid;$('#wifi-password').value='';$('#wifi-hidden').checked=w.hidden;$('#wifi-auto').checked=w.autoconnect;$('#wifi-name').focus();return}if(!confirm(op==='connect'?'Переключиться на '+w.ssid+'? Текущее соединение может прерваться.':'Удалить сохранённое подключение '+w.ssid+'?'))return;try{let d=await api('/api/feature/wifi',{method:'POST',body:JSON.stringify({op,uuid:w.uuid})});toast(d.message);loadWifi()}catch(e){toast(e.message)}}
$('#wifi-save').onclick=async()=>{try{let d=await api('/api/feature/wifi',{method:'POST',body:JSON.stringify({op:$('#wifi-uuid').value?'edit':'add',uuid:$('#wifi-uuid').value,name:$('#wifi-name').value,ssid:$('#wifi-ssid').value,password:$('#wifi-password').value,hidden:$('#wifi-hidden').checked,autoconnect:$('#wifi-auto').checked})});toast(d.message);clearWifi();loadWifi()}catch(e){toast(e.message)}};$('#wifi-confirm').onclick=async()=>{try{let d=await api('/api/feature/wifi',{method:'POST',body:JSON.stringify({op:'confirm'})});toast(d.message)}catch(e){toast(e.message)}};
let chatId=null;function bubble(role,text){let el=document.createElement('div');el.className='chat-bubble '+role;el.textContent=text;$('#chat-messages').append(el);el.scrollIntoView({block:'nearest'})}async function loadChats(){try{let d=await api('/api/chats');let root=$('#chat-list');root.replaceChildren();let filter=$('#chat-search').value.trim().toLocaleLowerCase();for(const c of d.chats.filter(x=>x.title.toLocaleLowerCase().includes(filter))){let row=document.createElement('div');row.className='discovery-item';let b=document.createElement('button');b.className='note-item';b.textContent=(c.id===chatId?'● ':'')+c.title;b.onclick=async()=>{try{let x=await api('/api/feature/chat-history',{method:'POST',body:JSON.stringify({chat_id:c.id})});chatId=c.id;$('#chat-messages').replaceChildren();x.messages.forEach(m=>bubble(m.role,m.content));loadChats()}catch(e){toast(e.message)}};let rename=document.createElement('button');rename.className='button secondary small-btn';rename.textContent='✎';rename.title='Переименовать';rename.onclick=async()=>{let title=prompt('Название диалога',c.title);if(title===null)return;try{let d=await api('/api/feature/chat-manage',{method:'POST',body:JSON.stringify({chat_id:c.id,op:'rename',title})});toast(d.message);loadChats()}catch(e){toast(e.message)}};let remove=document.createElement('button');remove.className='button secondary small-btn';remove.textContent='×';remove.title='Удалить';remove.onclick=async()=>{if(!confirm('Удалить диалог «'+c.title+'» и его сообщения?'))return;try{let d=await api('/api/feature/chat-manage',{method:'POST',body:JSON.stringify({chat_id:c.id,op:'delete'})});if(chatId===c.id){chatId=null;$('#chat-messages').replaceChildren()}toast(d.message);loadChats()}catch(e){toast(e.message)}};row.append(b,rename,remove);root.append(row)}if(!root.childElementCount)root.textContent='Диалоги не найдены.'}catch(e){toast(e.message)}}$('#chat-search').addEventListener('input',loadChats);$('#chat-new').onclick=()=>{chatId=null;$('#chat-messages').replaceChildren();$('#chat-input').focus();loadChats()};
$('#ai-keys-save').onclick=async()=>{try{let d=await api('/api/feature/ai-config',{method:'POST',body:JSON.stringify({groq:$('#groq-key').value,openrouter:$('#openrouter-key').value})});$('#groq-key').value='';$('#openrouter-key').value='';toast(d.message)}catch(e){toast(e.message)}};
$('#chat-send').onclick=async()=>{let input=$('#chat-input'),q=input.value.trim();if(!q)return;let provider=$('#chat-provider').value;if(provider!=='ollama'&&!confirm('Отправить сообщение и историю этого диалога провайдеру '+provider+'?'))return;let b=$('#chat-send');b.disabled=true;bubble('user',q);input.value='';$('#chat-status').textContent='Ожидаем ответ…';try{let d=await api('/api/feature/chat',{method:'POST',body:JSON.stringify({message:q,provider,model:$('#chat-model').value,chat_id:chatId,system_context:$('#chat-context').checked,vault_entry:$('#chat-secret').value,vault_master:$('#chat-secret').value?vaultMaster:undefined})});chatId=d.chat_id;bubble('assistant',d.answer);$('#chat-status').textContent='';loadChats()}catch(e){$('#chat-status').textContent=e.message}finally{b.disabled=false}};

async function loadBackup(){try{let d=await api('/api/backup');$('#backup-path').value=d.path||'';$('#backup-remote').value=d.remote||'';$('#backup-schedule').value=d.schedule||'off';let m=d.devices.length?'Подключённые носители: '+d.devices.map(x=>x.mount+' ('+x.size+')').join(', '):'Внешний носитель не обнаружен';m+=' · Rclone: '+(d.remotes.join(', ')||'подключений нет');if(d.last.message)m+=' · Последний результат: '+d.last.message;$('#backup-info').textContent=m}catch(e){toast(e.message)}}$('#backup-refresh').onclick=loadBackup;$('#backup-save').onclick=async()=>{try{let d=await api('/api/feature/backup-config',{method:'POST',body:JSON.stringify({path:$('#backup-path').value,remote:$('#backup-remote').value,schedule:$('#backup-schedule').value})});toast(d.message);loadBackup()}catch(e){toast(e.message)}};$('#backup-start').onclick=async()=>{if(!confirm('Создать зашифрованную резервную копию? На время копирования работающие сервисы будут остановлены.'))return;try{let d=await api('/api/feature/backup-start',{method:'POST',body:'{}'});toast(d.message)}catch(e){toast(e.message)}};

let selectedLimit=null;function openLimits(x){selectedLimit=x.id;$('#limits-service').textContent=x.name;$('#limits-memory').value=x.limits.memory?Math.round(x.limits.memory/1048576):2048;$('#limits-cpu').value=x.limits.cpus||4;$('#limits-dialog').showModal()}$('#limits-save').onclick=async e=>{e.preventDefault();try{let d=await api('/api/feature/limits',{method:'POST',body:JSON.stringify({service:selectedLimit,memory_mib:Number($('#limits-memory').value),cpus:Number($('#limits-cpu').value)})});$('#limits-dialog').close();toast(d.message);load()}catch(e){toast(e.message)}};
$('#password-save').onclick=async()=>{let current=$('#password-current').value,pw=$('#password-new').value;if(pw!==$('#password-repeat').value)return toast('Новые пароли не совпадают');try{let d=await api('/api/password',{method:'POST',body:JSON.stringify({current,password:pw})});$('#password-current').value='';$('#password-new').value='';$('#password-repeat').value='';showLogin();$('#login-error').textContent=d.message}catch(e){toast(e.message)}};
async function loadNetwork(){try{let d=await api('/api/network-inventory');if(!$('#scan-network').value)$('#scan-network').value=d.local.network||'';$('#scan-auto').checked=Boolean(d.auto.enabled&&d.auto.network===d.local.network);$('#scan-status').textContent=d.running.active?'Сканирование выполняется…':d.running.error||d.scan.message||'Нет результатов';let map=$('#network-map'),list=$('#network-hosts');map.replaceChildren();list.replaceChildren();let head=document.createElement('div');head.className='network-node';head.textContent='Raspberry Pi';let sub=document.createElement('small');sub.textContent=d.local.ip||'Нет адреса';head.append(sub);map.append(head);for(const h of d.scan.hosts||[]){let node=document.createElement('div');node.className='network-node';let name=document.createElement('strong');name.textContent=h.kind;let detail=document.createElement('small');detail.textContent=h.ip+(h.name?' · '+h.name:'');node.append(name,detail);let svc=document.createElement('div');svc.className='node-services';svc.textContent=(h.ports||[]).slice(0,6).map(p=>p.port+' '+p.service).join(' · ');node.append(svc);map.append(node);let row=document.createElement('div');row.className='network-host';let heading=document.createElement('strong');heading.textContent=h.ip+' · '+h.kind;let info=document.createElement('small');info.textContent=[h.name,h.vendor,h.mac].filter(Boolean).join(' · ');let ports=document.createElement('p');ports.textContent=h.ports.length?h.ports.map(p=>p.port+'/'+p.protocol+' '+p.service+(p.product?' · '+p.product:'')).join('  |  '):'Открытых портов не обнаружено в выбранном диапазоне';row.append(heading,info,ports);if(h.ports.some(p=>p.port===631&&p.protocol==='tcp')){let add=document.createElement('button');add.className='button secondary';add.textContent='Добавить IPP-принтер';add.onclick=()=>addPrinter(h.ip);row.append(add)}list.append(row)}if(!(d.scan.hosts||[]).length){let e=document.createElement('p');e.className='scan-empty';e.textContent='Результатов пока нет';list.append(e)}}catch(e){toast(e.message)}}
$('#scan-refresh').onclick=loadNetwork;$('#scan-start').onclick=async()=>{if(!$('#scan-authorized').checked)return toast('Подтвердите разрешение на сканирование');try{let d=await api('/api/feature/network-scan',{method:'POST',body:JSON.stringify({network:$('#scan-network').value,mode:$('#scan-mode').value,authorized:true})});toast(d.message);loadNetwork()}catch(e){toast(e.message)}};$('#scan-auto-save').onclick=async()=>{let enabled=$('#scan-auto').checked;if(enabled&&!$('#scan-authorized').checked)return toast('Подтвердите разрешение на сканирование');try{let d=await api('/api/feature/network-auto',{method:'POST',body:JSON.stringify({enabled,authorized:$('#scan-authorized').checked})});toast(d.message);loadNetwork()}catch(e){toast(e.message)}};setInterval(()=>{if($('#page-network').classList.contains('active'))loadNetwork()},15000);

async function addPrinter(ip){if(!confirm('Добавить принтер '+ip+' на эту Raspberry Pi? Убедитесь, что у вас есть разрешение на использование принтера.'))return;try{let d=await api('/api/feature/printer-add',{method:'POST',body:JSON.stringify({ip,authorized:true})});toast(d.message)}catch(e){toast(e.message)}}
async function loadHistory(){try{let d=await api('/api/network-history');let root=$('#known-networks');root.replaceChildren();for(const n of d.networks){let row=document.createElement('div');row.className='history-row';let info=document.createElement('div');let name=document.createElement('strong');name.textContent=n.name;let sub=document.createElement('small');sub.textContent=' · '+n.network+' · сканирований: '+n.scans+(n.auto_printers?' · автодобавление IPP':'');info.append(name,sub);let actions=document.createElement('div');for(const [label,fn] of [['Изменить',()=>editNetwork(n)],['В базу знаний',()=>networkKnowledge(n)],['Принтеры: '+(n.auto_printers?'вкл':'выкл'),()=>togglePrinterAuto(n)]]){let b=document.createElement('button');b.className='button small-btn secondary';b.textContent=label;b.onclick=fn;actions.append(b)}row.append(info,actions);root.append(row)}if(!d.networks.length)root.textContent='Сети появятся после первого сканирования.';root=$('#network-reports');root.replaceChildren();for(const r of d.reports){let row=document.createElement('div');row.className='history-row';let x=document.createElement('span');x.textContent=new Date(r.time*1000).toLocaleString('ru-RU')+' · '+r.network+' · устройств: '+r.hosts;let b=document.createElement('button');b.className='button small-btn secondary';b.textContent='Скачать HTML';b.onclick=()=>downloadReport(r.id);row.append(x,b);root.append(row)}if(!d.reports.length)root.textContent='Отчётов пока нет.'}catch(e){toast(e.message)}}
async function editNetwork(n){let name=prompt('Название сети',n.name);if(name===null)return;let description=prompt('Описание сети',n.description||'');if(description===null)return;try{let d=await api('/api/feature/network-save',{method:'POST',body:JSON.stringify({id:n.id,name,description,auto_printers:n.auto_printers,authorized:true})});toast(d.message);loadHistory()}catch(e){toast(e.message)}}
async function togglePrinterAuto(n){let enabled=!n.auto_printers;if(enabled&&!confirm('Автоматически добавлять IPP-принтеры, обнаруженные при сканировании этой сети? Подтвердите право пользоваться ими.'))return;try{let d=await api('/api/feature/network-save',{method:'POST',body:JSON.stringify({id:n.id,name:n.name,description:n.description||'',auto_printers:enabled,authorized:true})});toast(d.message);loadHistory()}catch(e){toast(e.message)}}
async function networkKnowledge(n){try{let d=await api('/api/feature/network-knowledge',{method:'POST',body:JSON.stringify({id:n.id})});toast(d.message)}catch(e){toast(e.message)}}
function downloadBlob(data,name,type){let a=document.createElement('a');let u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
async function downloadReport(id){try{let r=await fetch('/api/report-html',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(!r.ok)throw Error('Не удалось скачать отчёт');downloadBlob(await r.blob(),'pi-network-'+id+'.html','text/html')}catch(e){toast(e.message)}}
let vaultMaster=null,vaultTimer=null;function lockVault(){vaultMaster=null;clearTimeout(vaultTimer);$('#chat-secret').replaceChildren(new Option('Настроенный ключ провайдера',''));$('#node-secret').replaceChildren(new Option('Откройте хранилище',''));$('#ssh-secret').replaceChildren(new Option('Откройте хранилище',''));$('#vault-master').value='';$('#vault-master-confirm').value='';$('#vault-unlocked').classList.add('hidden');$('#vault-state').textContent='Закрыто';clearVault()}function vaultTouch(){clearTimeout(vaultTimer);vaultTimer=setTimeout(lockVault,600000)}function clearVault(){$('#vault-id').value='';$('#vault-title').value='';$('#vault-username').value='';$('#vault-secret').value='';$('#vault-url').value='';$('#vault-notes').value='';$('#vault-show').checked=false;$('#vault-secret').type='password'}async function vaultCall(op,d={}){if(!vaultMaster)throw Error('Сначала откройте хранилище');vaultTouch();return api('/api/vault/'+op,{method:'POST',body:JSON.stringify({master:vaultMaster,...d})})}async function loadVaultInfo(){try{let d=await api('/api/vault/info');$('#vault-create').disabled=d.exists;$('#vault-state').textContent=vaultMaster?'Открыто':d.exists?'Закрыто':'Хранилище ещё не создано'}catch(e){toast(e.message)}}
async function vaultEntries(){let d=await vaultCall('list');let sel=$('#chat-secret'),previous=sel.value;sel.replaceChildren(new Option('Настроенный ключ провайдера',''));for(const v of d.entries){let o=new Option('KDBX: '+v.title,v.id);sel.append(o)}if(d.entries.some(v=>v.id===previous))sel.value=previous;let nodeSel=$('#node-secret');nodeSel.replaceChildren(new Option('Выберите запись KDBX',''));for(const v of d.entries)nodeSel.append(new Option(v.title,v.id));let sshSel=$('#ssh-secret');sshSel.replaceChildren(new Option('Выберите запись KDBX',''));for(const v of d.entries)sshSel.append(new Option(v.title,v.id));let list=$('#vault-list');list.replaceChildren();for(const x of d.entries){let row=document.createElement('div');row.className='vault-row';row.dataset.search=(x.title+' '+x.username+' '+x.group).toLowerCase();let t=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=x.title;sub.textContent=[x.username,x.group].filter(Boolean).join(' · ');t.append(title,sub);let b=document.createElement('button');b.className='button small-btn secondary';b.textContent='Открыть';b.onclick=()=>vaultReveal(x.id);let actions=document.createElement('div');actions.className='vault-actions';if(x.username){let u=document.createElement('button');u.className='button small-btn secondary';u.textContent='Логин';u.title='Копировать логин';u.onclick=()=>copyValue(x.username,'Логин');actions.append(u)}let copy=document.createElement('button');copy.className='button small-btn secondary';copy.textContent='Пароль';copy.title='Копировать пароль';copy.onclick=()=>copyVaultSecret(x.id);actions.append(copy,b);row.append(t,actions);list.append(row)}if(!d.entries.length)list.textContent='Записей пока нет.'}async function vaultReveal(id){try{let d=await vaultCall('reveal',{id});$('#vault-id').value=id;$('#vault-title').value=d.title;$('#vault-username').value=d.username;$('#vault-secret').value=d.password;$('#vault-url').value=d.url;$('#vault-notes').value=d.notes;$('#vault-secret').type='password';$('#vault-show').checked=false}catch(e){toast(e.message)}}
$('#vault-open').onclick=async()=>{let p=$('#vault-master').value;if(!p)return toast('Введите мастер-пароль');vaultMaster=p;try{await vaultEntries();$('#vault-master').value='';$('#vault-unlocked').classList.remove('hidden');$('#vault-state').textContent='Открыто';vaultTouch()}catch(e){vaultMaster=null;toast(e.message)}};$('#vault-create').onclick=async()=>{let p=$('#vault-master').value;if(p.length<12)return toast('Минимум 12 символов');if(p!==$('#vault-master-confirm').value)return toast('Мастер-пароли не совпадают');if(!confirm('Создать хранилище с введённым мастер-паролем? Сохраните пароль: восстановить его невозможно.'))return;try{await api('/api/vault/create',{method:'POST',body:JSON.stringify({master:p})});vaultMaster=p;$('#vault-master').value='';$('#vault-master-confirm').value='';$('#vault-unlocked').classList.remove('hidden');$('#vault-state').textContent='Открыто';await vaultEntries();loadVaultInfo()}catch(e){toast(e.message)}};$('#vault-lock').onclick=lockVault;$('#vault-clear').onclick=clearVault;$('#vault-show').onchange=e=>{$('#vault-secret').type=e.target.checked?'text':'password';vaultTouch()};$('#vault-search').oninput=e=>{$$('.vault-row').forEach(x=>x.hidden=!x.dataset.search.includes(e.target.value.toLowerCase()));vaultTouch()};
$('#vault-save').onclick=async()=>{try{let d=await vaultCall('save',{id:$('#vault-id').value,title:$('#vault-title').value,username:$('#vault-username').value,password:$('#vault-secret').value,url:$('#vault-url').value,notes:$('#vault-notes').value});toast(d.message);clearVault();vaultEntries()}catch(e){toast(e.message)}};$('#vault-delete').onclick=async()=>{let id=$('#vault-id').value;if(!id)return toast('Выберите запись');if(!confirm('Удалить эту запись из KDBX?'))return;try{let d=await vaultCall('delete',{id});toast(d.message);clearVault();vaultEntries()}catch(e){toast(e.message)}};
$('#vault-services').onclick=async()=>{if(!confirm('Скопировать имеющиеся пароли сервисов Pi в зашифрованную базу? Исходный файл останется на месте.'))return;try{let d=await vaultCall('import-services');toast(d.message);vaultEntries()}catch(e){toast(e.message)}};$('#vault-export').onclick=async()=>{try{let d=await vaultCall('export');let raw=atob(d.data),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));downloadBlob(bytes,'pi-control.kdbx','application/octet-stream')}catch(e){toast(e.message)}};$('#vault-import').onclick=async()=>{let f=$('#vault-import-file').files[0];if(!f)return toast('Выберите файл KDBX');if(f.size>1800000)return toast('Файл больше 1,8 МБ');let r=new FileReader();r.onload=async()=>{try{let d=await vaultCall('import',{data:String(r.result).split(',')[1],import_master:$('#vault-import-password').value});$('#vault-import-password').value='';toast(d.message);vaultEntries()}catch(e){toast(e.message)}};r.readAsDataURL(f)};

async function copyValue(value,label){if(!value)return toast('Поле пустое');if(!navigator.clipboard||!window.isSecureContext)return toast('Копирование недоступно: используйте защищённое HTTPS-подключение.');try{await navigator.clipboard.writeText(value);toast(label+' скопирован');if(vaultMaster)vaultTouch()}catch(e){toast('Не удалось скопировать. Проверьте разрешение буфера обмена.')}}async function copyVaultSecret(id){try{let d=await vaultCall('reveal',{id});await copyValue(d.password,'Пароль')}catch(e){toast(e.message)}}$('#vault-copy-username').onclick=()=>copyValue($('#vault-username').value,'Логин');$('#vault-copy-secret').onclick=()=>copyValue($('#vault-secret').value,'Пароль');
$('#vault-generate').onclick=()=>{const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%_-';let out='';let bytes=new Uint8Array(64);while(out.length<24){crypto.getRandomValues(bytes);for(const b of bytes){if(b<Math.floor(256/chars.length)*chars.length)out+=chars[b%chars.length];if(out.length===24)break}}$('#vault-secret').value=out;$('#vault-secret').type='password';$('#vault-show').checked=false;if(vaultMaster)vaultTouch();toast('Пароль создан. Сохраните запись.')};
async function scanWifi(target){let root=$('#wifi-scan-results');root.textContent='Ищем точки доступа…';try{let d=await api('/api/feature/wifi-scan',{method:'POST',body:JSON.stringify({hidden_ssid:target||''})});root.replaceChildren();let note=document.createElement('p');note.className='fine-print';note.textContent=d.message;root.append(note);for(const w of d.networks){let row=document.createElement('div');row.className='discovery-item';let x=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small');title.textContent=w.ssid||'Скрытая сеть';meta.textContent=[w.active?'Подключено':'',w.security,'Сигнал '+w.signal+'%', 'Канал '+w.channel,w.bssid].filter(Boolean).join(' · ');x.append(title,meta);let b=document.createElement('button');b.className='button small-btn secondary';let saved=wifiProfiles.find(p=>p.ssid===w.ssid&&w.ssid);b.textContent=w.active?'Подключено':saved?'Подключить':w.hidden?'Указать SSID':'Добавить';b.disabled=w.active;b.onclick=()=>{if(saved)return wifiAction('connect',saved);clearWifi();$('#wifi-ssid').value=w.ssid||target||'';$('#wifi-name').value=w.ssid||target||'';$('#wifi-hidden').checked=!!w.hidden||!!target;$('#wifi-ssid').focus();if(/802\.1X|WPA-EAP|ENTERPRISE/i.test(w.security))toast('Корпоративная сеть: потребуются дополнительные параметры NetworkManager.');else toast(w.hidden&&!target?'Введите точный SSID и пароль ниже.':'Проверьте имя сети и введите пароль ниже.')};row.append(x,b);root.append(row)}if(!d.networks.length){let e=document.createElement('p');e.className='fine-print';e.textContent='Точки не найдены';root.append(e)}}catch(e){root.textContent=e.message}}$('#wifi-scan').onclick=()=>scanWifi('');$('#wifi-scan-hidden').onclick=()=>{let ssid=$('#wifi-directed').value.trim();if(!ssid)return toast('Введите известный SSID');scanWifi(ssid)};
$('#bluetooth-scan').onclick=async()=>{let root=$('#bluetooth-results'),button=$('#bluetooth-scan');button.disabled=true;root.textContent='Поиск Bluetooth-устройств…';try{let d=await api('/api/feature/bluetooth-scan',{method:'POST',body:'{}'});root.replaceChildren();let note=document.createElement('p');note.className='fine-print';note.textContent=d.message;root.append(note);for(const item of d.devices){let row=document.createElement('div');row.className='discovery-item';let x=document.createElement('div'),a=document.createElement('strong'),b=document.createElement('small');a.textContent=item.name;b.textContent=item.address+(item.seen?' · обнаружено при поиске':' · ранее известно');x.onclick=()=>{$('#bt-target').value=item.address};x.append(a,b);let inspect=document.createElement('button');inspect.className='button secondary small-btn';inspect.textContent='Сведения';inspect.onclick=async()=>{try{let d=await api('/api/feature/bluetooth-info',{method:'POST',body:JSON.stringify({address:item.address})});let pre=document.createElement('pre');pre.style.whiteSpace='pre-wrap';pre.textContent=Object.entries(d.details).map(([k,v])=>k+': '+v).concat(d.services.map(v=>'UUID: '+v)).join('\n')+'\n'+d.message;row.append(pre);inspect.disabled=true}catch(e){toast(e.message)}};let save=document.createElement('button');save.className='button secondary small-btn';save.textContent='В учёт';save.onclick=async()=>{let note=prompt('Заметка об устройстве','');if(note===null)return;try{let d=await api('/api/feature/bluetooth-record',{method:'POST',body:JSON.stringify({address:item.address,name:item.name,note})});toast(d.message);loadBluetoothInventory()}catch(e){toast(e.message)}};row.append(x,inspect,save);root.append(row)}if(!d.devices.length){let x=document.createElement('p');x.className='fine-print';x.textContent='Устройства не обнаружены';root.append(x)}}catch(e){root.textContent=e.message}finally{button.disabled=false}};

async function loadCluster(){try{let d=await api('/api/cluster');$('#node-local-fingerprint').textContent=d.fingerprint;let root=$('#node-list');root.replaceChildren();renderSshNodes(d.ssh_nodes||[]);for(const n of d.nodes){let box=document.createElement('div');box.className='node-card';let title=document.createElement('strong');title.textContent=n.name;let addr=document.createElement('small');addr.textContent=n.host+':'+n.port;let actions=document.createElement('div');actions.className='form-actions';let check=document.createElement('button');check.className='button secondary small-btn';check.textContent='Проверить';let remove=document.createElement('button');remove.className='button secondary small-btn';remove.textContent='Удалить';let result=document.createElement('div');result.className='node-result';check.onclick=()=>checkNode(n,result);remove.onclick=async()=>{if(!confirm('Удалить узел из панели?'))return;try{let x=await api('/api/feature/cluster-remove',{method:'POST',body:JSON.stringify({id:n.id})});toast(x.message);loadCluster()}catch(e){toast(e.message)}};let open=document.createElement('a');open.className='button secondary small-btn';open.href='https://'+n.host+':'+n.port+'/';open.target='_blank';open.rel='noopener noreferrer';open.textContent='Открыть панель';actions.append(check,open,remove);title.onclick=()=>checkNode(n,result);box.append(title,addr,actions,result);root.append(box);if((n.entry&&vaultMaster)||(!n.entry&&$('#node-manual-panel-password').value))checkNode(n,result)}if(!d.nodes.length)root.textContent='Узлы ещё не добавлены.'}catch(e){toast(e.message)}}
async function checkNode(n,root){if(n.entry&&!vaultMaster)return toast('Откройте хранилище KDBX');let panelPassword=n.entry?'':$('#node-manual-panel-password').value;if(!n.entry&&!panelPassword)return toast('Введите пароль панели узла');if(vaultMaster)vaultTouch();root.textContent='Проверяем узел…';try{let d=await api('/api/feature/cluster-action',{method:'POST',body:JSON.stringify({id:n.id,op:'status',master:vaultMaster,password:panelPassword})});root.replaceChildren();let x=document.createElement('p');x.className='fine-print';x.textContent='Температура: '+(d.system.temperature??'—')+' °C · Память: '+prettyBytes(d.system.memory_used)+' / '+prettyBytes(d.system.memory_total)+' · Диск: '+prettyBytes(d.system.disk_used)+' / '+prettyBytes(d.system.disk_total)+' · Нагрузка: '+(d.system.load??'—');root.append(x);for(const svc of d.services){let row=document.createElement('div');row.className='node-service';let t=document.createElement('span');t.textContent=svc.name+' · '+(svc.state==='running'?'работает':'остановлен');let b=document.createElement('button');b.className='button secondary small-btn';b.textContent=svc.state==='running'?'Остановить':'Запустить';b.onclick=async()=>{let action=svc.state==='running'?'stop':'start';if(!confirm((action==='stop'?'Остановить ':'Запустить ')+svc.name+' на '+n.name+'?'))return;try{let d=await api('/api/feature/cluster-action',{method:'POST',body:JSON.stringify({id:n.id,op:'service',service:svc.id,action,master:vaultMaster,password:panelPassword})});toast(d.message)}catch(e){toast(e.message)}};row.append(t,b);root.append(row)}}catch(e){root.textContent=e.message}}
$('#node-refresh').onclick=loadCluster;$('#node-add').onclick=async()=>{if(!vaultMaster)return toast('Сначала откройте хранилище KDBX');try{let d=await api('/api/feature/cluster-add',{method:'POST',body:JSON.stringify({name:$('#node-name').value,host:$('#node-host').value,port:Number($('#node-port').value),fingerprint:$('#node-fingerprint').value,entry:$('#node-secret').value})});toast(d.message);loadCluster()}catch(e){toast(e.message)}};

async function loadInterfaces(){let root=$('#interfaces-list');try{let d=await api('/api/interfaces');root.replaceChildren();for(let x of d.interfaces){let p=document.createElement('p');p.className='fine-print';p.textContent=x.kind+' · '+x.device+' · '+(x.addresses.join(', ')||'нет IPv4')+' · шлюз '+(x.gateway||'нет')+(x.primary?' · основной маршрут':'')+(x.metric!==null?' · метрика '+x.metric:'');root.append(p);if(x.gateway&&!x.primary){let b=document.createElement('button');b.className='button secondary small-btn';b.textContent='Сделать основным · '+x.device;b.onclick=async()=>{if(!confirm('Предпочесть '+x.device+' для интернета? Открытые соединения могут прерваться. Второй интерфейс останется включённым.'))return;b.disabled=true;try{let r=await api('/api/feature/interface-prefer',{method:'POST',body:JSON.stringify({device:x.device})});toast(r.message);loadInterfaces()}catch(e){toast(e.message);b.disabled=false}};root.append(b)}}let n=document.createElement('p');n.className='fine-print';n.textContent=d.message;root.append(n)}catch(e){root.textContent=e.message}}
$('#interfaces-refresh').onclick=loadInterfaces;

$('#knowledge-files').onclick=()=>{go('files');fm.left.kind='remote';fm.left.root='knowledge';fm.left.path='';fm.active='left';fmLoad('left')};

function sshPayload(){return {host:$('#ssh-host').value.trim(),port:Number($('#ssh-port').value)}}
$('#ssh-key-check').onclick=async()=>{try{let d=await api('/api/feature/ssh-fingerprint',{method:'POST',body:JSON.stringify(sshPayload())});$('#ssh-key-fingerprint').value=d.fingerprint;toast('Проверьте отпечаток на удалённом устройстве')}catch(e){toast(e.message)}};
$('#ssh-scan').onclick=async()=>{let root=$('#ssh-scan-results'),button=$('#ssh-scan');if(!$('#ssh-scan-authorized').checked)return toast('Подтвердите разрешение на сканирование сети');button.disabled=true;root.textContent='Ищем SSH в текущей сети…';try{let d=await api('/api/feature/ssh-discover',{method:'POST',body:JSON.stringify({authorized:true})});root.replaceChildren();for(let host of d.hosts){let b=document.createElement('button');b.className='button secondary small-btn';b.textContent=host;b.onclick=()=>{$('#ssh-host').value=host};root.append(b)}let p=document.createElement('p');p.className='fine-print';p.textContent=d.message;root.append(p)}catch(e){root.textContent=e.message}finally{button.disabled=false}};
$('#ssh-add').onclick=async()=>{if(!sshManualSecret()&&!vaultMaster)return toast('Введите SSH-секрет вручную или откройте KDBX');if(!confirm('Отпечаток SSH сверен с отпечатком на удалённом устройстве через доверенный канал?'))return;try{let d=await api('/api/feature/ssh-add',{method:'POST',body:JSON.stringify({...sshPayload(),name:$('#ssh-name').value,username:$('#ssh-user').value,auth:$('#ssh-auth').value,fingerprint:$('#ssh-key-fingerprint').value,entry:sshManualSecret()?'':$('#ssh-secret').value,secret:sshManualSecret(),master:vaultMaster})});$('#ssh-manual').value='';$('#ssh-manual-key').value='';toast(d.message);loadCluster()}catch(e){toast(e.message)}};
function renderSshNodes(nodes){let root=$('#ssh-nodes');root.replaceChildren();for(let n of nodes){let card=document.createElement('article');card.className='node-card';let title=document.createElement('strong');title.textContent=n.name;let host=document.createElement('small');host.textContent=n.host+':'+n.port+' · '+n.model;let actions=document.createElement('div');actions.className='form-actions';let check=document.createElement('button');check.className='button secondary small-btn';check.textContent='Проверить';let setup=document.createElement('button');setup.className='button primary small-btn';setup.textContent='Автонастройка';setup.hidden=true;let detail=document.createElement('pre');detail.className='fine-print';check.onclick=async()=>{detail.textContent='Подключение…';setup.hidden=true;try{let d=await api('/api/feature/ssh-status',{method:'POST',body:JSON.stringify(sshAuth(n))});detail.textContent=Object.entries(d.fields).map(([k,v])=>k+': '+v).join('\n');setup.hidden=!(d.fields.ROOT==='yes'&&d.fields.PANEL==='absent')}catch(e){detail.textContent=e.message}};setup.onclick=async()=>{try{let auth=sshAuth(n);let panelPassword=$('#node-manual-panel-password').value;if(!vaultMaster&&panelPassword.length<12)return toast('Откройте KDBX или задайте отдельный пароль панели от 12 символов');setup.disabled=true;let d=await api('/api/feature/node-provision',{method:'POST',body:JSON.stringify({...auth,master:vaultMaster||'',panel_password:panelPassword})});$('#node-manual-panel-password').value='';detail.textContent=d.message;async function follow(){try{let x=await api('/api/feature/node-provision-status',{method:'POST',body:JSON.stringify({job:d.job})});detail.textContent=x.message||x.state;if(x.state==='running')setTimeout(follow,2000);else{setup.disabled=false;if(x.state==='done'){toast(x.message);loadCluster()}}}catch(e){detail.textContent=e.message;setup.disabled=false}}follow()}catch(e){setup.disabled=false;toast(e.message)}};let remove=document.createElement('button');remove.className='button secondary small-btn';remove.textContent='Удалить';remove.onclick=async()=>{if(!confirm('Удалить SSH-узел из панели?'))return;try{let d=await api('/api/feature/ssh-remove',{method:'POST',body:JSON.stringify({id:n.id})});toast(d.message);loadCluster()}catch(e){toast(e.message)}};actions.append(check,setup,remove);card.append(title,host,actions,detail);root.append(card)}if(!nodes.length)root.textContent='SSH-узлы пока не добавлены.'}

async function loadBluetoothInventory(){try{let d=await api('/api/bluetooth-inventory');let root=$('#bluetooth-inventory');root.replaceChildren();for(let x of d.devices){let p=document.createElement('p');p.className='fine-print';p.textContent=[x.name,x.address,x.note].filter(Boolean).join(' · ');root.append(p)}if(!d.devices.length)root.textContent='Учёт пока пуст.'}catch(e){toast(e.message)}}
$('#bluetooth-inventory-refresh').onclick=loadBluetoothInventory;

const kb={path:'',items:[],selected:null,editing:null};
function kbPath(name){return kb.path?kb.path+'/'+name:name}
async function kbLoad(){try{let d=await fmOp('list',{root:'knowledge',path:kb.path});kb.items=d.items;$('#kb-path').textContent='/'+kb.path;kbRender()}catch(e){$('#kb-status').textContent=e.message}}
function kbRender(){let root=$('#kb-list'),q=$('#kb-search').value.trim().toLocaleLowerCase();root.replaceChildren();for(let item of kb.items){if(!item.name.toLocaleLowerCase().includes(q))continue;let row=document.createElement('div');row.className='kb-row'+(kb.selected===item.name?' selected':'');let b=document.createElement('button');b.className='button secondary small-btn';b.textContent=(item.directory?'📁 ':'📄 ')+item.name;b.onclick=async()=>{kb.selected=item.name;if(item.directory){kb.path=kbPath(item.name);kb.selected=null;await kbLoad()}else{kbRender();if(/\.(md|txt|markdown)$/i.test(item.name))await kbOpen(item.name);else{$('#kb-current').textContent=item.name;$('#kb-status').textContent='Вложение: можно скачать или открыть в файловом менеджере.';kb.editing=null}}};row.append(b);root.append(row)}if(!root.childElementCount)root.textContent='Папка пуста или совпадений нет.'}
async function kbOpen(name){try{let path=kbPath(name),d=await fmOp('read',{root:'knowledge',path});kb.editing={path,modified:d.modified};$('#kb-current').textContent=name;$('#kb-text').value=d.text;$('#kb-render').hidden=true;$('#kb-text').hidden=false;$('#kb-status').textContent='Открыто · '+path}catch(e){$('#kb-status').textContent=e.message}}
$('#kb-search').oninput=kbRender;$('#kb-refresh').onclick=kbLoad;$('#kb-up').onclick=()=>{kb.path=kb.path.split('/').slice(0,-1).join('/');kb.selected=null;kbLoad()};
$('#kb-folder').onclick=async()=>{let name=prompt('Название новой папки');if(!name)return;try{await fmOp('mkdir',{root:'knowledge',path:kb.path,name});await kbLoad()}catch(e){toast(e.message)}};
$('#kb-new').onclick=async()=>{let name=prompt('Название заметки');if(!name)return;if(!/\.(md|txt)$/i.test(name))name+='.md';try{await fmOp('touch',{root:'knowledge',path:kb.path,name});await kbLoad();kb.selected=name;await kbOpen(name)}catch(e){toast(e.message)}};
$('#kb-save').onclick=async()=>{if(!kb.editing)return toast('Откройте заметку');try{let d=await fmOp('write',{root:'knowledge',...kb.editing,text:$('#kb-text').value});toast(d.message);let refreshed=await fmOp('read',{root:'knowledge',path:kb.editing.path});kb.editing.modified=refreshed.modified;loadKnowledge()}catch(e){toast(e.message)}};
$('#kb-preview').onclick=()=>{let r=$('#kb-render'),t=$('#kb-text');if(!r.hidden){r.hidden=true;t.hidden=false;return}r.replaceChildren();for(let line of t.value.split('\n')){let m=/^(#{1,3})\s+(.*)$/.exec(line),el=document.createElement(m?'h'+m[1].length:'div');el.textContent=m?m[2]:line||' ';r.append(el)}r.hidden=false;t.hidden=true};
$('#kb-upload-btn').onclick=()=>$('#kb-upload').click();$('#kb-upload').onchange=async e=>{for(let f of e.target.files){try{await fmUploadFile(f,{kind:'remote',root:'knowledge',path:kb.path})}catch(err){toast(err.message);break}}e.target.value='';kbLoad()};
$('#kb-rename').onclick=async()=>{if(!kb.selected)return toast('Выберите файл');let name=prompt('Новое имя',kb.selected);if(!name)return;try{await fmOp('rename',{root:'knowledge',path:kbPath(kb.selected),name});kb.selected=null;kb.editing=null;kbLoad()}catch(e){toast(e.message)}};
$('#kb-delete').onclick=async()=>{if(!kb.selected||!confirm('Удалить «'+kb.selected+'» без корзины?'))return;try{await fmOp('delete',{root:'knowledge',path:kbPath(kb.selected)});kb.selected=null;kb.editing=null;$('#kb-text').value='';kbLoad()}catch(e){toast(e.message)}};
$('#kb-download').onclick=()=>{if(!kb.selected)return toast('Выберите файл');let i=kb.items.find(x=>x.name===kb.selected);if(!i||i.directory)return toast('Выберите файл');fmDownload({root:'knowledge',path:kbPath(i.name),item:i})};

async function btRun(mode){let address=$('#bt-target').value.trim(),authorized=$('#bt-authorized').checked;if(mode!=='info'&&!authorized)return toast('Подтвердите разрешение владельца');let out=$('#bt-result');out.textContent='Проверяем…';try{let d=await api('/api/feature/bluetooth-audit',{method:'POST',body:JSON.stringify({address,mode,authorized})});out.textContent=d.result+'\n'+d.message}catch(e){out.textContent=e.message}}
for(let mode of ['info','ping','services'])$('#bt-'+mode).onclick=()=>btRun(mode);
for(let action of ['connect','disconnect','trust','untrust'])$('#bt-'+action).onclick=async()=>{if(!$('#bt-authorized').checked)return toast('Подтвердите разрешение владельца');try{let d=await api('/api/feature/bluetooth-action',{method:'POST',body:JSON.stringify({address:$('#bt-target').value,action,authorized:true})});$('#bt-result').textContent=d.result;toast(d.message)}catch(e){toast(e.message)}};
$('#bt-history-refresh').onclick=async()=>{try{let d=await api('/api/bluetooth-history'),root=$('#bt-history');root.replaceChildren();for(let x of d.history.slice(0,100)){let el=document.createElement('details'),sum=document.createElement('summary'),pre=document.createElement('pre');sum.textContent=new Date(x.time*1000).toLocaleString('ru-RU')+' · '+x.address+' · '+x.mode;pre.className='ai-answer';pre.textContent=x.result;el.append(sum,pre);root.append(el)}if(!root.childElementCount)root.textContent='Проверок пока нет.'}catch(e){toast(e.message)}};

async function wifiDiagnostic(){try{let d=await api('/api/wifi-observations');$('#wifi-live').textContent='Состояние: '+(d.state||'—')+' · IPv4: '+(d.internal_ip||'нет')+' · сигнал: '+(d.signal?d.signal+' %':'неизвестен');await loadWifi()}catch(e){toast(e.message)}}
$('#wifi-diag-refresh').onclick=wifiDiagnostic;$('#wifi-external-refresh').onclick=async()=>{try{await api('/api/feature/wifi-external',{method:'POST',body:'{}'});toast('Проверка завершена; доступность адреса зависит от Wi‑Fi');await wifiDiagnostic()}catch(e){toast(e.message)}};
$('#wifi-log-refresh').onclick=async()=>{try{let [a,b]=await Promise.all([api('/api/wifi-observations'),api('/api/wifi-journal')]);$('#wifi-log').textContent=a.events.map(x=>new Date(x.time*1000).toLocaleString('ru-RU')+' · '+x.message+' · '+x.uuid).concat(b.lines).join('\n')||'Записей пока нет.';$('#wifi-log').parentNode.open=true}catch(e){toast(e.message)}};
async function diskPoll(){try{let d=await api('/api/disk-usage');$('#disk-message').textContent=d.running?'Измерение выполняется…':d.error||('Обновлено '+(d.time?new Date(d.time*1000).toLocaleString('ru-RU'):'—'));let table=$('#disk-table'),chart=$('#disk-chart');table.replaceChildren();chart.replaceChildren();let total=d.rows.reduce((n,x)=>n+x.bytes,0)||1;let legend=document.createElement('div');legend.className='disk-legend';let top=d.rows.slice(0,6),remaining=d.rows.slice(6).reduce((n,x)=>n+x.bytes,0);for(let [i,x] of top.entries()){let part=document.createElement('span');part.className='disk-segment disk-color-'+i;part.style.width=(x.bytes/total*100)+'%';part.title=x.path+' · '+prettyBytes(x.bytes);chart.append(part);let l=document.createElement('span');l.textContent=x.path+' '+prettyBytes(x.bytes);l.className='disk-legend-item disk-color-text-'+i;legend.append(l)}if(remaining){let part=document.createElement('span');part.className='disk-segment disk-color-other';part.style.width=(remaining/total*100)+'%';part.title='Остальные · '+prettyBytes(remaining);chart.append(part)}table.append(legend);let details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Все каталоги · '+d.rows.length;details.append(summary);for(let x of d.rows){let row=document.createElement('div');row.className='disk-row';let name=document.createElement('span');name.textContent=x.path;let value=document.createElement('strong');value.textContent=prettyBytes(x.bytes);row.append(name,value);details.append(row)}if(d.rows.length)table.append(details);if(d.running)setTimeout(diskPoll,2500)}catch(e){$('#disk-message').textContent=e.message}}
$('#disk-scan').onclick=async()=>{try{await api('/api/feature/disk-usage',{method:'POST',body:'{}'});diskPoll()}catch(e){toast(e.message)}};
const themeMedia=window.matchMedia('(prefers-color-scheme: dark)');function setAppearance(){let theme=localStorage.getItem('pi-theme')||'light',bg=localStorage.getItem('pi-background')||'plain';document.documentElement.dataset.theme=theme==='system'?(themeMedia.matches?'dark':'light'):theme;document.documentElement.dataset.bg=bg;$('#appearance-theme').value=theme;$('#appearance-bg').value=bg}
$('#appearance-theme').onchange=e=>{localStorage.setItem('pi-theme',e.target.value);setAppearance()};$('#appearance-bg').onchange=e=>{localStorage.setItem('pi-background',e.target.value);setAppearance()};themeMedia.addEventListener('change',setAppearance);setAppearance();
function buildSettingsNav(){let nav=$('#settings-shortcuts');nav.replaceChildren();let headings=[...document.querySelectorAll('#page-settings .panel h2')].filter(h=>h.textContent.trim()!=='Разделы настроек');headings.forEach((h,i)=>{h.id=h.id||'settings-section-'+i;let b=document.createElement('button');b.className='button secondary small-btn';b.textContent=h.textContent.trim();b.onclick=()=>h.scrollIntoView({behavior:'smooth',block:'start'});nav.append(b)})}buildSettingsNav();

let termId='',termTimer=null,termView=null,termFit=null,termWriteQueue=Promise.resolve();
function termInit(){if(termView)return;termView=new Terminal({cursorBlink:true,scrollback:2500,fontSize:13,theme:{background:'#101d18',foreground:'#d5f2df'}});termFit=new FitAddon.FitAddon();termView.loadAddon(termFit);termView.open($('#terminal-emulator'));termView.onData(data=>termWrite(data));termView.onResize(size=>{let id=termId;if(id)api('/api/feature/terminal-resize',{method:'POST',body:JSON.stringify({id,cols:size.cols,rows:size.rows})}).catch(()=>{})});window.addEventListener('resize',()=>{if($('#page-terminal').classList.contains('active'))termFit.fit()});}
function termWrite(data){if(!termId)return;let id=termId;termWriteQueue=termWriteQueue.then(()=>api('/api/feature/terminal-write',{method:'POST',body:JSON.stringify({id,data})})).catch(e=>{$('#terminal-state').textContent=e.message})}
async function termPoll(){if(!termId)return;let id=termId;try{let d=await api('/api/feature/terminal-read',{method:'POST',body:JSON.stringify({id})});if(id!==termId)return;if(d.data)termView.write(d.data);if(!d.running){termId='';$('#terminal-state').textContent='Сессия завершена.';return}termTimer=setTimeout(termPoll,300)}catch(e){if(id===termId){termId='';$('#terminal-state').textContent=e.message}}}
$('#terminal-start').onclick=async()=>{if(termId)return toast('Терминал уже открыт');try{termInit();let d=await api('/api/feature/terminal-start',{method:'POST',body:JSON.stringify($('#terminal-target').value?{...sshAuth(sshNodeCache.find(n=>n.id===$('#terminal-target').value),$('#terminal-secret').value),node_id:$('#terminal-target').value}:{})});termId=d.id;termView.reset();$('#terminal-state').textContent=d.message;termFit.fit();await api('/api/feature/terminal-resize',{method:'POST',body:JSON.stringify({id:termId,cols:termView.cols,rows:termView.rows})});termPoll();termView.focus()}catch(e){toast(e.message)}};
$('#terminal-form').onsubmit=e=>{e.preventDefault();if(!termId)return toast('Откройте терминал');let input=$('#terminal-input');termWrite(input.value+'\r');input.value='';termView.focus()};
$('#terminal-stop').onclick=async()=>{if(!termId)return;clearTimeout(termTimer);let id=termId;termId='';try{let d=await api('/api/feature/terminal-stop',{method:'POST',body:JSON.stringify({id})});$('#terminal-state').textContent=d.message}catch(e){toast(e.message)}};
$('#terminal-target').onchange=async()=>{if(!termId)return;await $('#terminal-stop').onclick();$('#terminal-start').click()};
async function termTargets(){try{let d=await api('/api/cluster'),sel=$('#terminal-target'),old=sel.value;sel.replaceChildren(new Option('Основной Raspberry Pi',''));sshNodeCache=d.ssh_nodes||[];for(let n of sshNodeCache)sel.append(new Option(n.name+' · '+n.host,n.id));sel.value=old}catch(e){toast(e.message)}}

let sshNodeCache=[];function sshAuth(n,manual=''){if(!n)throw Error('Узел не найден');manual=manual||sshManualSecret();if(manual)return {id:n.id,secret:manual};if(n.entry){if(!vaultMaster)throw Error('Откройте KDBX');vaultTouch();return {id:n.id,master:vaultMaster}}let secret=prompt('SSH-пароль или приватный ключ для '+n.name);if(!secret)throw Error('SSH-секрет не введён');return {id:n.id,secret}}
let nodeopsPath='';function nodeopsPayload(){let id=$('#nodeops-target').value;if(!id)throw Error('Выберите SSH-узел');return sshAuth(sshNodeCache.find(n=>n.id===id))}
async function nodeopsTargets(){try{let d=await api('/api/cluster'),s=$('#nodeops-target'),old=s.value;s.replaceChildren(new Option('Выберите узел',''));sshNodeCache=d.ssh_nodes||[];for(let n of sshNodeCache)s.append(new Option(n.name+' · '+n.host,n.id));s.value=old}catch(e){toast(e.message)}}
$('#nodeops-refresh').onclick=nodeopsTargets;$('#nodeops-target').onchange=()=>{nodeopsPath='';$('#nodeops-output').replaceChildren()};
$('#nodeops-containers').onclick=async()=>{try{let d=await api('/api/feature/node-containers',{method:'POST',body:JSON.stringify(nodeopsPayload())}),root=$('#nodeops-output');root.replaceChildren();$('#nodeops-path').textContent='';for(let x of d.containers){let row=document.createElement('div');row.className='history-row';let label=document.createElement('span');label.textContent=x.name+' · '+x.state+' · '+x.image;row.append(label);for(let [op,title] of [['start','Запустить'],['stop','Остановить'],['restart','Перезапустить']]){let b=document.createElement('button');b.className='button secondary small-btn';b.textContent=title;b.onclick=async()=>{if(!confirm(title+' контейнер '+x.name+'?'))return;try{let z=await api('/api/feature/node-container-action',{method:'POST',body:JSON.stringify({...nodeopsPayload(),container:x.name,action:op})});toast(z.message);$('#nodeops-containers').click()}catch(e){toast(e.message)}};row.append(b)}root.append(row)}if(!d.containers.length)root.textContent='Контейнеры не найдены.'}catch(e){toast(e.message)}};
async function nodeopsFiles(){try{let d=await api('/api/feature/node-files',{method:'POST',body:JSON.stringify({...nodeopsPayload(),path:nodeopsPath})}),root=$('#nodeops-output');root.replaceChildren();$('#nodeops-path').textContent=d.base+(d.path?'/'+d.path:'');if(nodeopsPath){let up=document.createElement('button');up.className='button secondary small-btn';up.textContent='↑ Выше';up.onclick=()=>{nodeopsPath=nodeopsPath.split('/').slice(0,-1).join('/');nodeopsFiles()};root.append(up)}for(let x of d.items){let row=document.createElement('div');row.className='history-row';let b=document.createElement('button');b.className='button secondary small-btn';b.textContent=(x.directory?'📁 ':'📄 ')+x.name+(x.symlink?' · ссылка':'');b.disabled=!x.directory||x.symlink;b.onclick=()=>{nodeopsPath=nodeopsPath?nodeopsPath+'/'+x.name:x.name;nodeopsFiles()};row.append(b);let size=document.createElement('span');size.className='fine-print';size.textContent=x.directory?'Папка':prettyBytes(x.size);row.append(size);root.append(row)}if(!d.items.length)root.append(document.createTextNode('Папка пуста.'))}catch(e){toast(e.message)}}
$('#nodeops-files').onclick=()=>{nodeopsPath='';nodeopsFiles()};$('#nodeops-terminal').onclick=()=>{let id=$('#nodeops-target').value;if(!id)return toast('Выберите SSH-узел');go('terminal');termTargets().then(()=>{$('#terminal-target').value=id})};

function sshManualSecret(){return $('#ssh-auth').value==='key'?$('#ssh-manual-key').value:$('#ssh-manual').value}
